WITH valid AS (SELECT id, customer_id, device, browser, started_at, country, TRIM(device) AS clean_device, HOUR(started_at) AS started_at_hour FROM sessions WHERE started_at >= TIMESTAMP '2023-09-10 01:00:00' AND customer_id IS NOT NULL), gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM valid), sessionized AS (SELECT id, customer_id, device, browser, started_at, clean_device, started_at_hour, SUM(is_new_session) OVER (PARTITION BY device ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN started_at_hour >= 65 THEN 'HIGH' ELSE 'LOW' END AS started_at_hour_tier, customer_id, CASE WHEN session_no >= 7 THEN 'LARGE' ELSE 'SMALL' END AS session_no_tier, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, COUNT(DISTINCT browser) AS distinct_browsers, COUNT_IF(device = 'desktop') AS desktop_events, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list FROM sessionized GROUP BY CASE WHEN started_at_hour >= 65 THEN 'HIGH' ELSE 'LOW' END, customer_id, CASE WHEN session_no >= 7 THEN 'LARGE' ELSE 'SMALL' END HAVING duration_min < 1000000 ORDER BY distinct_browsers ASC;
